let rulesActiveChapter = 'intro';
let rulesSearchIsOpen = false;
let rulesSearchEntries = null;

function normalizeRuleText(v) { return String(v ?? '').toLocaleLowerCase('ru').replaceAll('ё','е').replace(/\s+/g,' ').trim(); }
function ruleBlockPlainText(html) { const t=document.createElement('div');t.innerHTML=html.replace(/<(?:p|li|div|ul|ol|section)\b/gi,match=>' '+match).replace(/<\/(?:p|li|div|ul|ol|section)>/gi,match=>match+' ');return t.textContent.replace(/\s+/g,' ').trim(); }
function ruleEscape(value) { return escapeHtml(String(value)); }
// Short stems catch ordinary Russian word forms: «порча», «порчу», «порчи».
const RULES_SEARCH_STEMS=['порч','оберег','считк','считыв','сущност','экзорц','суккуб','призрак','привид','характерист','ритуал','атрибут','торг','здоров','обряд','колод','маст','рандом','способност'];
function ruleSearchNeedle(query) {
  const q=normalizeRuleText(query);
  if (!q || q.includes(' ') || q.length<4) return q;
  return RULES_SEARCH_STEMS.find(stem => q.startsWith(stem)) || q;
}
function highlightRuleText(value, query) {
  const valueText=String(value);
  const target=ruleSearchNeedle(query);
  if (!target) return ruleEscape(valueText);
  const haystack=valueText.toLocaleLowerCase('ru').replaceAll('ё','е');
  let at=0,out='';
  for (;;) {
    const found=haystack.indexOf(target,at);
    if (found===-1) break;
    let end=found+target.length;
    if (target!==normalizeRuleText(query)) {
      while (end<valueText.length && /[а-яё]/i.test(valueText[end])) end++;
    }
    out+=ruleEscape(valueText.slice(at,found))+'<mark class="rules-highlight">'+ruleEscape(valueText.slice(found,end))+'</mark>';
    at=end;
  }
  return out+ruleEscape(valueText.slice(at));
}
function markRuleMatches(parent, query) {
  const wanted=ruleSearchNeedle(query);
  if (!wanted) return;
  const walker=document.createTreeWalker(parent, NodeFilter.SHOW_TEXT);
  const matches=[];
  while (walker.nextNode()) {
    const node=walker.currentNode;
    if (node.parentElement?.closest('mark,button')) continue;
    if (normalizeRuleText(node.nodeValue).includes(wanted)) matches.push(node);
  }
  for (const node of matches) {
    const fragment=document.createElement('span');
    fragment.innerHTML=highlightRuleText(node.nodeValue, query);
    node.replaceWith(...fragment.childNodes);
  }
}
function setupRuleSearchIndex() {
  if (rulesSearchEntries) return;
  rulesSearchEntries=[];
  for (const chapter of RULES_CHAPTERS) {
    for (const block of chapter.blocks) {
      rulesSearchEntries.push({chapterId:chapter.id,chapter:chapter.short,title:block.title,blockId:block.id,plain:ruleBlockPlainText(block.html)});
    }
  }
}
function renderRulesTabs() {
  const nav=$('#rules-tabs');
  nav.replaceChildren();
  RULES_CHAPTERS.forEach((chapter,index)=>{
    const tab=document.createElement('button');
    tab.type='button';
    tab.className='rules-tab';
    tab.dataset.chapter=chapter.id;
    tab.innerHTML=`<span class="rules-tab-num">${String(index+1).padStart(2,'0')}</span><span class="rules-tab-name">${ruleEscape(chapter.short)}</span>`;
    tab.addEventListener('click',()=>{
      $('#rules-search').value='';
      $('#rules-clear').hidden=true;
      if (chapter.id !== rulesActiveChapter || rulesSearchIsOpen) selectRulesChapter(chapter.id);
    });
    window.ExorcistBookmarks?.mount(tab);
    nav.appendChild(tab);
  });
}
function updateRulesTabActive() {
  $$('#rules-tabs .rules-tab').forEach(button=>{
    const selected=button.dataset.chapter===rulesActiveChapter;
    button.classList.toggle('active',selected);
    button.setAttribute('aria-current',selected?'page':'false');
  });
  // On mobile the chapter rail scrolls horizontally. Keep the selected
  // chapter in view when jumping from a full-text search result.
  const rail=$('#rules-tabs');
  if (window.matchMedia('(max-width:760px)').matches) {
    const active=rail.querySelector('.rules-tab.active');
    if (active) {
      const a = active.getBoundingClientRect(), r = rail.getBoundingClientRect();
      if (a.left < r.left || a.right > r.right) rail.scrollTo({left:Math.max(0,rail.scrollLeft + a.left-r.left-(rail.clientWidth-a.width)/2),behavior:prefersStillness()?'instant':'smooth'});
    }
  }
}
function selectRulesChapter(chapterId, query='', blockId='') {
  const paper = $('#rules-paper');
  const oldIndex = RULES_CHAPTERS.findIndex(c => c.id === rulesActiveChapter);
  const nextIndex = RULES_CHAPTERS.findIndex(c => c.id === chapterId);
  const changed = chapterId !== rulesActiveChapter || rulesSearchIsOpen || !!query;
  const commit = () => paintRulesChapter(chapterId, query, blockId);
  if (changed && $('#rules-dialog').open && !paper.hidden && window.ExorcistBinding) {
    window.ExorcistBinding.turn(paper, $('#rules-scroll'), commit, nextIndex < oldIndex ? -1 : 1);
  } else {
    window.ExorcistBinding?.cancel(paper);
    commit();
  }
}
function paintRulesChapter(chapterId, query='', blockId='') {
  const idx=RULES_CHAPTERS.findIndex(c=>c.id===chapterId);
  const chapter=RULES_CHAPTERS[idx===-1?0:idx];
  rulesActiveChapter=chapter.id;
  rulesSearchIsOpen=false;
  updateRulesTabActive();
  $('#rules-results').hidden=true;
  const paper=$('#rules-paper');
  paper.hidden=false;
  paper.dataset.chapter=chapter.id;
  let html=`<div class="rules-page-heading"><span class="rules-page-number">ГЛАВА ${String(idx+1).padStart(2,'0')} / 07</span><h3>${ruleEscape(chapter.title)}</h3><p>${ruleEscape(chapter.subtitle)}</p></div>`;
  if (chapter.facts.length && !['intro','suits'].includes(chapter.id)) {
    html+='<div class="rules-facts" style="--fact-count:'+chapter.facts.length+'">'+chapter.facts.map(f=>`<div class="rules-fact"><strong>${ruleEscape(f[0])}</strong><span>${ruleEscape(f[1])}</span></div>`).join('')+'</div>';
  }
  if (query) html+='<button id="rules-back-results" class="rules-back-results" type="button">← Ко всем результатам поиска</button>';
  // Lead with the objective and the two phases; the original story follows.
  const blocks=chapter.id==='intro'
    ? ['win','phases','story'].map(id=>chapter.blocks.find(block=>block.id===id))
    : chapter.blocks;
  const keyRules=new Set(['win','deal','refill','unlock','matching','wards']);
  html+=blocks.map(b=>`<section class="rules-block${keyRules.has(b.id)?' rule-key':''}${b.id==='story'?' rule-context':''}" id="rule-block-${b.id}" data-rules-block="${b.id}"><div class="rules-block-heading"><h4>${ruleEscape(b.title)}</h4></div><div class="rules-block-body">${b.html}</div></section>`).join('');
  paper.innerHTML=html;
  if (query) {
    markRuleMatches(paper,query);
    $('#rules-back-results').addEventListener('click',()=>showRuleSearch());
  }
  const viewport=$('#rules-scroll');
  viewport.scrollTop=0;
  if (blockId) {
    requestAnimationFrame(()=>{
      const target=paper.querySelector(`[data-rules-block="${blockId}"]`);
      if (!target) return;
      const difference=target.getBoundingClientRect().top-viewport.getBoundingClientRect().top;
      viewport.scrollTop+=difference-16;
    });
  }
}
function ruleSearchExcerpt(text,query) {
  const q=ruleSearchNeedle(query), lower=normalizeRuleText(text);
  const index=Math.max(0,lower.indexOf(q));
  let start=Math.max(0,index-66),end=Math.min(text.length,index+q.length+111);
  if (start>0) {const s=text.indexOf(' ',start);if(s>=0&&s<index)start=s+1;}
  if (end<text.length) {const e=text.lastIndexOf(' ',end);if(e>index+q.length)end=e;}
  return (start?'…':'')+text.slice(start,end)+(end<text.length?'…':'');
}
function showRuleSearch() {
  window.ExorcistBinding?.cancel($('#rules-paper'));
  const query=$('#rules-search').value.trim();
  if (!query) {selectRulesChapter(rulesActiveChapter);return;}
  setupRuleSearchIndex();
  rulesSearchIsOpen=true;
  $('#rules-paper').hidden=true;
  const root=$('#rules-results');
  root.hidden=false;
  const normalized=ruleSearchNeedle(query);
  const items=rulesSearchEntries.filter(row=>normalizeRuleText(row.plain+' '+row.title+' '+row.chapter).includes(normalized));
  const count=items.length;
  root.innerHTML=`<div class="rules-results-head"><span>ПОИСК ПО ВСЕМ ГЛАВАМ</span><h3>${count?`Найдено ${count} ${count===1?'совпадение':(count%10>=2&&count%10<=4&&(count%100<12||count%100>14)?'совпадения':'совпадений')}`:'Ничего не найдено'}</h3><p>${count?'Нажмите на результат, чтобы перейти к нужному месту в правилах.':'Попробуйте другое слово: «считка», «оберег», «урон», «торговля».'}</p></div>`;
  const list=document.createElement('div');list.className='rules-result-list';
  for (const item of items.slice(0,40)) {
    const chapterIndex=RULES_CHAPTERS.findIndex(c=>c.id===item.chapterId);
    const result=document.createElement('button');result.type='button';result.className='rules-result';
    const excerpt=ruleSearchExcerpt(item.plain,query);
    result.innerHTML=`<span class="rules-result-overline">ГЛАВА ${String(chapterIndex+1).padStart(2,'0')} · ${ruleEscape(item.chapter)}</span><strong>${highlightRuleText(item.title,query)}</strong><span class="rules-result-excerpt">${highlightRuleText(excerpt,query)}</span><span class="rules-result-more">Открыть раздел →</span>`;
    result.addEventListener('click',()=>selectRulesChapter(item.chapterId,query,item.blockId));
    list.appendChild(result);
  }
  root.appendChild(list);
  if (count>40) root.insertAdjacentHTML('beforeend',`<p class="rules-results-more">Показаны первые 40 фрагментов из ${count}. Уточните запрос.</p>`);
  $('#rules-scroll').scrollTop=0;
}
function openRules() {
  const dialog=$('#rules-dialog');
  $('#rules-search').value='';
  $('#rules-clear').hidden=true;
  renderRulesTabs();
  selectRulesChapter(rulesActiveChapter);
  if (!dialog.open) openAppDialog(dialog);
}
function closeRules() {
  window.ExorcistBinding?.cancel($('#rules-paper'));
  const dialog=$('#rules-dialog');
  if (dialog.open) closeAppDialog(dialog);
}
function setupRulesEvents() {
  $('#open-rules-home').addEventListener('click', event => {
    if (window.ExorcistProps) window.ExorcistProps.activate(event.currentTarget, openRules);
    else openRules();
  });
  $('#open-rules-game').addEventListener('click', event => {
    if (window.ExorcistProps) window.ExorcistProps.activate(event.currentTarget, openRules);
    else openRules();
  });
  $('#rules-close').addEventListener('click',closeRules);
  $('#rules-dialog').addEventListener('click',(event)=>{if(event.target===$('#rules-dialog'))closeRules();});
  $('#rules-search').addEventListener('input',()=>{
    const hasQuery=!!$('#rules-search').value.trim();
    $('#rules-clear').hidden=!hasQuery;
    if (hasQuery) showRuleSearch(); else selectRulesChapter(rulesActiveChapter);
  });
  $('#rules-clear').addEventListener('click',()=>{
    $('#rules-search').value='';$('#rules-clear').hidden=true;selectRulesChapter(rulesActiveChapter);$('#rules-search').focus();
  });
}

function setupEvents() {
  setupRulesEvents();
  $('#mode-local').addEventListener('click', openLocalSetup);
  $('#open-entity-book-home').addEventListener('click', event => {
    if (window.ExorcistProps) window.ExorcistProps.activate(event.currentTarget, openEntityBook);
    else openEntityBook();
  });
  $('#open-entity-book-game').addEventListener('click', event => {
    if (window.ExorcistProps) window.ExorcistProps.activate(event.currentTarget, openEntityBook);
    else openEntityBook();
  });
  $('#entity-picker-toggle').addEventListener('click', () => {
    const panel = $('#entity-picker-panel');
    if (!panel) return;
    setEntityPicker($('#entity-picker-toggle').getAttribute('aria-expanded') !== 'true');
  });
  $('#entity-prev').addEventListener('click', () => stepEntityBook(-1));
  $('#entity-next').addEventListener('click', () => stepEntityBook(1));
  $('#open-magic-ball-home').addEventListener('click', event => {
    if (window.ExorcistProps) window.ExorcistProps.activate(event.currentTarget, openMagicBall);
    else openMagicBall();
  });
  $('#open-magic-ball-game').addEventListener('click', event => {
    if (window.ExorcistProps) window.ExorcistProps.activate(event.currentTarget, openMagicBall);
    else openMagicBall();
  });
  $('#magic-ball').addEventListener('click', rollMagicBall);
  document.getElementById('magic-ball-ios-switch')?.addEventListener('change', rollMagicBall);
  window.addEventListener('resize', () => {if ($('#magic-ball-dialog')?.open) setupIOSBallTap();},{passive:true});
  $('#enable-magic-motion').addEventListener('click', requestMagicMotionPermission);
  document.addEventListener('visibilitychange', () => {
    if (document.hidden) stopMagicMotion();
    else if ($('#magic-ball-dialog')?.open) prepareMagicMotion();
  });
  window.addEventListener('pagehide', stopMagicMotion);
  $('#magic-ball-close').addEventListener('click', closeMagicBall);
  $('#magic-ball-dialog').addEventListener('click', event => { if (event.target === $('#magic-ball-dialog')) closeMagicBall(); });
  $('#magic-ball-dialog').addEventListener('cancel', event => { event.preventDefault(); closeMagicBall(); });
  $('#entity-book-close').addEventListener('click', closeEntityBook);
  $('#entity-book-dialog').addEventListener('click', event => { if (event.target === $('#entity-book-dialog')) closeEntityBook(); });
  $('#entity-book-dialog').addEventListener('cancel', event => {event.preventDefault(); closeEntityBook();});
  $('#mode-online').addEventListener('click', () => showScreen('online-screen'));
  $('#continue-local').addEventListener('click', continueLocalGame);
  $$('.back-home').forEach(b => b.addEventListener('click', goHome));
  $('#local-count').addEventListener('change', renderLocalNameInputs);
  $('#start-local').addEventListener('click', startLocalGame);
  $('#host-create').addEventListener('click', createOnlineLobby);
  $('#join-button').addEventListener('click', joinOnlineLobby);
  $('#join-code').addEventListener('input', e => { e.target.value = e.target.value.replace(/\D/g,'').slice(0,4); });
  $('#start-online-game').addEventListener('click', startOnlineGame);
  $('#copy-lobby-code').addEventListener('click', copyLobbyCode);
  $('#share-lobby').addEventListener('click', openShare);
  $('#share-button').addEventListener('click', openShare);
  $('#copy-share').addEventListener('click', copyShare);
  $('#native-share').addEventListener('click', nativeShare);
  $('#restart-button').addEventListener('click', () => { pendingRestart = true; openAppDialog($('#restart-dialog')); });
  $('#restart-dialog').addEventListener('close', () => {
    if (pendingRestart && $('#restart-dialog').returnValue === 'confirm') restartGame();
    pendingRestart = false;
  });
  $('#leave-game').addEventListener('click', goHome);
  window.addEventListener('beforeinstallprompt', event => {
    event.preventDefault(); installPrompt = event; $('#install-button').classList.remove('hidden');
  });
  $('#install-button').addEventListener('click', async () => {
    if (!installPrompt) return;
    installPrompt.prompt(); await installPrompt.userChoice; installPrompt = null; $('#install-button').classList.add('hidden');
  });
}

function boot() {
  setupEvents();
  renderHome();
  renderLocalNameInputs();
  const join = new URLSearchParams(location.search).get('join');
  if (/^\d{4}$/.test(join || '')) {
    $('#join-code').value = join;
    showScreen('online-screen');
  } else {
    showScreen('home-screen');
  }
  if ('serviceWorker' in navigator && /^https?:$/.test(location.protocol)) {
    window.addEventListener('load', () => navigator.serviceWorker.register('./service-worker.js').catch(() => {}));
  }
}

boot();
